"""
title: Token Count Display
description: Intercepts the final stream chunk to read real token usage and display it as a status. Uses the stream hook which actually works reliably in Open WebUI.
author: you
version: 2.0.0
"""

import json
import time
from typing import Any, AsyncGenerator, Awaitable, Callable, Optional
from pydantic import BaseModel, Field


class Filter:
    class Valves(BaseModel):
        show_tokens_per_second: bool = Field(default=True, description="Show tok/s")
        show_session_totals: bool = Field(
            default=True, description="Cumulative session totals"
        )

    def __init__(self):
        self.valves = self.Valves()
        self._session_input: dict[str, int] = {}
        self._session_output: dict[str, int] = {}
        self._start_time: dict[str, float] = {}

    def inlet(self, body: dict, __metadata__: Optional[dict] = None) -> dict:
        chat_id = (__metadata__ or {}).get("chat_id", "default")
        self._start_time[chat_id] = time.monotonic()
        return body

    async def stream(
        self,
        event: dict,
        __event_emitter__: Callable[[dict], Awaitable[None]],
        __metadata__: Optional[dict] = None,
    ) -> dict:
        chat_id = (__metadata__ or {}).get("chat_id", "default")

        # The final SSE chunk (done=true for Ollama, or the [DONE] sentinel for OpenAI)
        # carries usage. We look for it here.
        usage = None

        # Ollama final chunk format
        if event.get("done") is True:
            usage = {
                "input": event.get("prompt_eval_count", 0),
                "output": event.get("eval_count", 0),
            }

        # OpenAI-style: usage block on the last chunk
        if "usage" in event and event["usage"]:
            u = event["usage"]
            usage = {
                "input": u.get("prompt_tokens") or u.get("input_tokens") or 0,
                "output": u.get("completion_tokens") or u.get("output_tokens") or 0,
            }

        if usage and (usage["input"] or usage["output"]):
            inp = usage["input"]
            out = usage["output"]

            self._session_input[chat_id] = self._session_input.get(chat_id, 0) + inp
            self._session_output[chat_id] = self._session_output.get(chat_id, 0) + out

            tps_str = ""
            if self.valves.show_tokens_per_second and out > 0:
                start = self._start_time.get(chat_id)
                if start:
                    elapsed = time.monotonic() - start
                    if elapsed > 0:
                        tps_str = f"  |  {out / elapsed:.1f} tok/s"

            parts = [
                f"Tokens - In: {inp:,}  Out: {out:,}  Total: {inp + out:,}{tps_str}"
            ]

            #            if self.valves.show_session_totals:
            #                si = self._session_input[chat_id]
            #                so = self._session_output[chat_id]
            #                parts.append(f"Session — In: {si:,}  Out: {so:,}  Total: {si + so:,}")

            await __event_emitter__(
                {
                    "type": "status",
                    "data": {
                        "description": "   ·   ".join(parts),
                        "done": True,
                    },
                }
            )

        return event

    async def outlet(self, body: dict, __metadata__: Optional[dict] = None) -> dict:
        # Intentionally minimal — no event emitter, no blocking calls.
        # All display work is done in stream() above.
        return body
